# ====================== 2. 核心功能函數 ======================
def _generate_default_limits(s_df):
    """從 Scores 表自動推導項目代碼，或自動產生 A1-E20 的預設項目。"""
    # 建立預設的 A1-E20 項目代碼清單 (A1-A20, B1-B20... E1-E20)
    default_codes = [f"{prefix}{num}" for prefix in ['A', 'B', 'C', 'D', 'E'] for num in range(1, 21)]
    
    if s_df is None or s_df.empty:
        return pd.DataFrame({
            'code': default_codes,
            'full_name': default_codes,
            'max_score': 100
        })

    # 向量化提取代碼 (支援 A1-E99)
    extracted = s_df['subject'].astype(str).str.extract(r'^([A-Ea-e]\d{1,2})', expand=False)
    mask = extracted.notna()
    if not mask.any():
        return pd.DataFrame({
            'code': default_codes,
            'full_name': default_codes,
            'max_score': 100
        })
        
    temp = pd.DataFrame({
        'code': extracted[mask].str.upper(),
        'full_name': s_df.loc[mask, 'subject'].astype(str)
    })
    # 去重：保留每個 code 第一次出現的全名
    temp = temp.drop_duplicates(subset='code', keep='first').copy()
    temp['max_score'] = 100
    
    # 排序
    temp['_letter'] = temp['code'].str[0]
    temp['_num'] = temp['code'].str[1:].astype(int)
    temp = temp.sort_values(['_letter', '_num']).drop(columns=['_letter', '_num']).reset_index(drop=True)
    return temp


def _get_db_mtime():
    """取得資料庫檔案的最後修改時間，作為快取鍵。"""
    if os.path.exists(DB_FILE):
        return os.path.getmtime(DB_FILE)
    return 0


@st.cache_data(show_spinner="正在載入資料庫...")
def load_data(_mtime=None):
    """讀取 Users / Scores / Limits 三個 Sheet（Limits 不存在時自動產生預設）。
    強制字串欄位為 str 型態，避免 data_editor 型態衝突。
    使用 @st.cache_data 快取，以 _mtime 作為快取鍵。"""
    if os.path.exists(DB_FILE):
        try:
            u_df = pd.read_excel(DB_FILE, sheet_name='Users', engine='openpyxl',
                                 dtype={'username': str, 'password': str, 'student_id': str, 'name': str})
            s_df = pd.read_excel(DB_FILE, sheet_name='Scores', engine='openpyxl',
                                 dtype={'student_id': str, 'category': str, 'subject': str})
            try:
                l_df = pd.read_excel(DB_FILE, sheet_name='Limits', engine='openpyxl',
                                     dtype={'code': str, 'full_name': str})
                if l_df is None or l_df.empty:
                    raise ValueError("empty")
            except Exception:
                l_df = _generate_default_limits(s_df)
            return u_df, s_df, l_df
        except Exception:
            return None, None, None
    return None, None, None


def save_data(u_df, s_df, l_df=None):
    """寫回 Users / Scores / Limits。l_df 為 None 時沿用檔案中既有的 Limits。
    使用臨時文件寫入後替換，避免 Windows 文件佔用問題。"""
    import tempfile, shutil, time

    if l_df is None and os.path.exists(DB_FILE):
        try:
            l_df = pd.read_excel(DB_FILE, sheet_name='Limits', engine='openpyxl')
        except Exception:
            l_df = None

    # 先寫入臨時文件
    dir_name = os.path.dirname(os.path.abspath(DB_FILE))
    tmp_fd, tmp_path = tempfile.mkstemp(suffix='.xlsx', dir=dir_name)
    os.close(tmp_fd)
    try:
        with pd.ExcelWriter(tmp_path, engine='openpyxl') as writer:
            u_df.to_excel(writer, sheet_name='Users', index=False)
            s_df.to_excel(writer, sheet_name='Scores', index=False)
            if l_df is not None and not l_df.empty:
                l_df.to_excel(writer, sheet_name='Limits', index=False)
        # 嘗試替換原文件（最多重試 3 次）
        for attempt in range(3):
            try:
                shutil.move(tmp_path, DB_FILE)
                # 清除快取，確保下次讀取最新資料
                load_data.clear()
                _build_scores_with_names.clear()
                return  # 成功
            except PermissionError:
                if attempt < 2:
                    time.sleep(0.5)
                else:
                    raise PermissionError(
                        f"無法寫入 {DB_FILE}，請確認該檔案未被 Excel 或其他程式開啟，然後重試。"
                    )
    except Exception:
        # 清理臨時文件
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise




def validate_score_limits(edited_scores, original_scores, df_limits):
    """
    對照 df_limits 中的 max_score 校驗 edited_scores（向量化版本）。
    超過上限的項目使用 original_scores 的舊值替代，回傳 (校正後 df, 違規明細列表)。
    """
    if df_limits is None or df_limits.empty:
        return edited_scores.reset_index(drop=True), []

    # 建立 limit_map: code -> max_score
    limit_map = {}
    for _, r in df_limits.iterrows():
        if pd.notna(r['code']) and pd.notna(r['max_score']):
            limit_map[str(r['code']).strip().upper()] = int(r['max_score'])

    if not limit_map:
        return edited_scores.reset_index(drop=True), []

    edited = edited_scores.copy().reset_index(drop=True)

    # 向量化提取 code
    codes = edited['subject'].astype(str).str.extract(r'^([A-Ea-e]\d{1,2})', expand=False).str.upper()
    max_vals = codes.map(limit_map)
    scores = pd.to_numeric(edited['score'], errors='coerce')

    # 找出超限行
    exceed_mask = scores.notna() & max_vals.notna() & (scores > max_vals)

    violations = []
    if exceed_mask.any():
        # 使用複合鍵向量化查找原始分數
        e_key = edited['student_id'].astype(str).str.strip() + '|' + edited['subject'].astype(str).str.strip()
        o_key = original_scores['student_id'].astype(str).str.strip() + '|' + original_scores['subject'].astype(str).str.strip()
        orig_score_series = pd.Series(
            pd.to_numeric(original_scores['score'], errors='coerce').fillna(0).astype(int).values,
            index=o_key.values
        )
        orig_score_series = orig_score_series[~orig_score_series.index.duplicated(keep='first')]
        original_mapped = e_key.map(orig_score_series).fillna(0).astype(int)

        for i in edited.index[exceed_mask]:
            old_val = original_mapped.at[i]
            violations.append({
                'student_id': str(edited.at[i, 'student_id']).strip(),
                'subject': str(edited.at[i, 'subject']).strip(),
                'attempted': int(scores.at[i]), 'max': int(max_vals.at[i]), 'restored': int(old_val),
            })
            edited.at[i, 'score'] = int(old_val)

    return edited, violations


def validate_no_decrease(edited_scores, original_scores):
    """
    教師專用校驗：分數只能增加不能減少（全向量化版本）。
    將減少的項目還原為原始值，回傳 (校正後 df, 違規明細列表)。
    """
    edited = edited_scores.copy().reset_index(drop=True)

    # 使用複合鍵進行向量化匹配
    e_key = edited['student_id'].astype(str).str.strip() + '|' + edited['subject'].astype(str).str.strip()
    o_key = original_scores['student_id'].astype(str).str.strip() + '|' + original_scores['subject'].astype(str).str.strip()

    # 建立原始分數的 Series（以複合鍵為索引）
    orig_score_series = pd.Series(
        pd.to_numeric(original_scores['score'], errors='coerce').fillna(0).astype(int).values,
        index=o_key.values
    )
    orig_score_series = orig_score_series[~orig_score_series.index.duplicated(keep='first')]

    # 向量化映射原始分數
    original_mapped = e_key.map(orig_score_series)
    new_scores = pd.to_numeric(edited['score'], errors='coerce')

    # 向量化找出減分行
    decrease_mask = new_scores.notna() & original_mapped.notna() & (new_scores < original_mapped)

    decrease_violations = []
    if decrease_mask.any():
        for i in edited.index[decrease_mask]:
            decrease_violations.append({
                'student_id': str(edited.at[i, 'student_id']).strip(),
                'subject': str(edited.at[i, 'subject']).strip(),
                'attempted': int(new_scores.at[i]),
                'original': int(original_mapped.at[i]),
            })
            edited.at[i, 'score'] = int(original_mapped.at[i])

    return edited, decrease_violations


def merge_summary_scores(uploaded_file, df_users, df_scores):
    """
    讀取「學生成績匯總表」格式的 xlsx，純加分模式整合到 df_scores。
    表格特殊結構：第一欄標題為 name 但實際存放學號，第二欄標題為 student_id 但實際存放姓名。
    後續欄位為項目代碼（A1~E10）。
    儲存格數字 > 0 時表示加分，0 / 空白 / NaN 表示跳過。
    支援部分項目欄位缺失的情況。
    回傳：(更新後的 df_scores, 更新項目數, 跳過項目數)
    """
    import re
    raw = pd.read_excel(uploaded_file, sheet_name=0, engine='openpyxl', dtype=str)

    if raw.shape[1] < 3:
        raise ValueError("上傳的檔案欄位不足，至少需要學號欄和一個項目代碼欄")

    # ── 第一欄（不管表頭叫什麽）作為 student_id ──
    sid_col = raw.columns[0]

    # ── 識別所有合法的項目代碼欄（A1~E10 格式）──
    code_re = re.compile(r'^[A-Ea-e]\d{1,2}$')
    code_cols = [c for c in raw.columns[2:] if isinstance(c, str) and code_re.match(c.strip())]

    # ── 建立 (student_id, subject_code) → 索引 的快速查找表（向量化）──
    subj_re = re.compile(r'^([A-Ea-e]\d{1,2})')
    df_scores = df_scores.copy()
    codes_series = df_scores['subject'].astype(str).str.extract(r'^([A-Ea-e]\d{1,2})', expand=False).str.upper()
    sids_series = df_scores['student_id'].astype(str).str.strip()
    mask = codes_series.notna()
    index_map = {}
    if mask.any():
        keys = list(zip(sids_series[mask], codes_series[mask]))
        indices = df_scores.index[mask]
        for k, idx in zip(keys, indices):
            index_map[k] = idx

    valid_sids = set(df_users['student_id'].astype(str).str.strip())

    updated, skipped = 0, 0
    for _, row in raw.iterrows():
        sid = str(row[sid_col]).strip()
        if not sid or sid.lower() == 'nan':
            continue
        if sid not in valid_sids:
            skipped += sum(
                1 for c in code_cols
                if pd.notna(row.get(c)) and str(row.get(c)).strip() not in ('', 'nan', '0', '0.0')
            )
            continue

        for col in code_cols:
            cell = row.get(col)
            if pd.isna(cell):
                continue
            cell_str = str(cell).strip()
            if cell_str == '' or cell_str.lower() == 'nan':
                continue

            try:
                add_val = int(float(cell_str))
            except ValueError:
                skipped += 1
                continue

            if add_val <= 0:
                continue

            code = col.strip().upper()
            target_idx = index_map.get((sid, code))
            if target_idx is None:
                skipped += 1
                continue

            df_scores.at[target_idx, 'score'] = int(df_scores.at[target_idx, 'score']) + add_val
            updated += 1

    return df_scores, updated, skipped


@st.cache_data(show_spinner=False)
def _build_scores_with_names(_s_df, _u_df, _mtime=None):
    """將姓名欄合併到成績表（快取版本，避免每次 rerun 都複製 46K 行）。"""
    name_map = dict(zip(_u_df['student_id'].astype(str), _u_df['name'].astype(str)))
    result = _s_df.copy()
    result.insert(1, 'name', result['student_id'].map(name_map).fillna('—'))
    return result, name_map


